"""Ordinary procedure, current priorities and protection of participants."""
import json,sys
from pathlib import Path
CPP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm'
LAW='https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14994.htm'
STF='https://portal.stf.jus.br/noticias/verNoticiaDetalhe.asp?idConteudo=540018'
rows={}
def add(n,s,p,a,c,v,q,t,d,links=()):
 rows['art-'+str(n)]=dict(simples=s,pontos=p,atencao=[a],exemplo=c+' Variação: '+v,prova=q,termos=[dict(termo=t,significado=d)],remissoes=[CPP,*links])
add(394,'Procedimento é comum ou especial; no comum, distinguir ordinário, sumário e sumaríssimo.', ['Ordinário: pena máxima igual ou superior a quatro anos.', 'Sumário: pena máxima inferior a quatro, ressalvado enquadramento sumaríssimo/especial.', 'Sumaríssimo: infração de menor potencial na forma da lei.', 'Júri: arts. 406–497.', 'Subsidiariedade do ordinário exige compatibilidade.', 'Remissão 395–398 não restaura art. 398 revogado.'], 'Usar pena máxima cominada, não pena concreta; exatamente quatro pertence ao ordinário.', 'Crime com máximo de quatro anos, sem rito especial, segue ordinário.', 'Infração de menor potencial deve ser examinada segundo regime sumaríssimo, não tratada indistintamente como sumária.', ['Exatamente quatro anos entra no ordinário? Sim.', 'Pena concreta define por si o rito do artigo? Não.'], 'Procedimento comum','Rito definido pela lei e natureza da infração.')
add('394-a','Lei 14.994/2024 ampliou prioridade aos processos de violência contra a mulher, além dos hediondos, em todas as instâncias.', ['Isenção de custas, taxas e despesas nos processos de violência contra mulher, salvo má-fé.', 'Isenção apenas à vítima e, se morta, familiares enumerados quando titulares da representação, queixa ou prosseguimento.', 'Prioridade não elimina contraditório.'], 'Não estender isenção ao acusado nem a qualquer pessoa só porque há processo prioritário.', 'Vítima utiliza a isenção prevista em processo de violência contra mulher.', 'Acusado não recebe essa isenção apenas pelo §1º; verificar eventual fundamento diverso.', ['Prioridade se limita à primeira instância? Não.', 'A isenção deste artigo beneficia automaticamente acusado? Não.'], 'Prioridade e isenção','Benefícios processuais de alcance e destinatários definidos.',[LAW])
add(395,'Rejeição da denúncia ou queixa ocorre por inépcia manifesta, falta de pressuposto/condição ou ausência de justa causa.', ['Três fundamentos distintos.', 'Justa causa exige suporte para instaurar ação, não certeza de condenação.', 'Parágrafo único revogado não deve ser recuperado.'], 'Não confundir rejeição inicial com absolvição após instrução.', 'Acusação não descreve conduta de modo apto à defesa: examinar inépcia.', 'Descrição apta, mas sem suporte mínimo, exige examinar justa causa em vez de condenar antecipadamente.', ['Rejeição é sentença condenatória? Não.', 'Justa causa exige certeza final de culpa? Não.'], 'Rejeição inicial','Controle de admissibilidade da acusação.')
add(396,'Sem rejeição liminar, no ordinário e sumário juiz recebe acusação e cita para resposta escrita em dez dias.', ['Não confundir oferecimento com recebimento.', 'Por edital: prazo começa com comparecimento pessoal do acusado ou defensor constituído.', 'Ausência por edital deve ser integrada ao art. 366.'], 'Não contar automaticamente dez dias de defesa apenas da publicação do edital.', 'Acusado citado regularmente apresenta resposta por defensor no prazo legal.', 'Edital sem comparecimento e sem defensor constituído exige avaliar suspensão, não presumir defesa perdida.', ['Resposta escrita tem dez dias? Sim.', 'Edital inicia sempre prazo por sua publicação? Não.'], 'Resposta à acusação','Manifestação defensiva inicial após citação.')
add('396-a','Resposta permite preliminares, argumentos defensivos, documentos, justificações, especificação de prova e testemunhas.', ['Qualificar testemunhas e pedir intimação se necessária.', 'Exceção processa-se em apartado.', 'Sem resposta ou sem defensor constituído: nomeação e vista por dez dias.'], 'Não prosseguir sem resposta técnica apenas porque acusado deixou transcorrer prazo.', 'Defensor apresenta tese preliminar, documento e rol com qualificação.', 'Sem advogado constituído, juiz nomeia defensor e assegura vista por dez dias.', ['Exceção é processada em apartado? Sim.', 'Falta de resposta dispensa defesa técnica? Não.'], 'Defesa inicial técnica','Preparação das teses e das provas da defesa.')
add(397,'Após resposta, absolvição sumária cabe por excludente manifesta, atipicidade evidente ou punibilidade extinta.', ['I: excludente de ilicitude manifesta.', 'II: excludente de culpabilidade manifesta, salvo inimputabilidade.', 'III: fato evidentemente não é crime; IV: extinção de punibilidade.', 'Distinguir absolvição sumária comum do art. 415 no júri.'], 'Inimputabilidade foi ressalvada no inciso II; não impor medida de segurança sumária por diagnóstico.', 'Documento incontroverso demonstra atipicidade evidente: examinar absolvição sumária.', 'Excludente dependente de prova controvertida não é automaticamente manifesta para este momento.', ['Inimputabilidade está incluída sem ressalva no inciso II? Não.', 'Atipicidade evidente é fundamento? Sim.'], 'Absolvição sumária','Encerramento nas hipóteses legais verificáveis antes da instrução.')
add(399,'Juiz agenda instrução e intima sujeitos pertinentes; preso é requisitado e quem presidiu instrução deve sentenciar.', ['Intimar acusado, defesa, MP e querelante/assistente se aplicável.', 'Poder público providencia apresentação do preso.', 'Identidade física do juiz não elimina exame de substituições legalmente justificadas.'], 'Não afirmar que a falta de presença física do preso autoriza suprimir interrogatório ou defesa.', 'Audiência é designada com comunicação regular e providências de apresentação.', 'Alteração de juiz exige examinar motivo e regime de substituição, não nulidade automática sem análise.', ['Defensor precisa ser intimado? Sim.', 'Apresentação do preso depende de providência pública? Sim.'], 'Identidade física do juiz','Ligação entre instrução presidida e sentença, integrada ao regime judicial.')
add(400,'Instrução ordinária tem prazo máximo legal de sessenta dias e interrogatório após a produção de provas enumerada.', ['Ofendido; testemunhas acusação e defesa, ressalvado art. 222.', 'Esclarecimentos periciais, acareações e reconhecimento; depois acusado.', 'Concentração numa audiência; provas irrelevantes, impertinentes ou protelatórias podem ser indeferidas.', 'Esclarecimento pericial depende de requerimento prévio.'], 'Prazo não gera soltura automática isoladamente; indeferimento de prova deve respeitar defesa e fundamentação.', 'Defesa conhece depoimentos e demais provas antes do interrogatório.', 'Prova pertinente não pode ser recusada apenas porque desfavorece acusação.', ['Interrogatório antecede todas as testemunhas neste rito? Não.', 'Esclarecimento do perito requer pedido prévio? Sim.'], 'Concentração da instrução','Produção ordenada de prova com interrogatório ao final.')
add('400-a','Todos no ato devem preservar integridade física e psicológica da vítima; juiz impede ataques estranhos aos fatos e ofensivos.', ['Regra da audiência, especialmente crimes sexuais.', 'Vedadas circunstâncias alheias e linguagem/material ofensivos à vítima ou testemunha.', 'ADPF 1107: não desqualificar mulher por histórico sexual ou modo de vida.', 'Responsabilidades possíveis são civil, penal e administrativa, conforme apuração.'], 'Direito de defesa não autoriza humilhação; questionamento pertinente sobre fatos exige respeito e limites.', 'Pergunta sobre dinâmica do fato é feita de modo respeitoso e pertinente.', 'Insinuação sobre vida sexual para desacreditar mulher exige intervenção judicial, não tolerância como técnica defensiva.', ['Proteção alcança testemunha na vedação de ofensa? Sim.', 'Ampla defesa permite humilhar a vítima? Não.'], 'Proteção na audiência','Garantia de participação sem desqualificação ofensiva.',[STF])
add(401,'No ordinário, acusação e defesa podem arrolar até oito testemunhas cada, com exclusões legais da contagem.', ['Não contar as sem compromisso e as referidas nesse limite.', 'Desistência é possível, ressalvada iniciativa pertinente do art. 209.', 'Distinguir limite de ritos especiais ou sumário.'], 'Oito é por lado neste rito, não teto único para todo processo penal.', 'Acusação indica oito e defesa oito testemunhas do rol ordinário.', 'Testemunha referida durante depoimento exige exame próprio e não é somada automaticamente ao limite.', ['Oito é total compartilhado pelas partes? Não.', 'Referidas integram essa contagem? Não.'], 'Rol ordinário','Limite de testemunhas com exclusões previstas.')
add(402,'Ao final da prova podem ser pedidas diligências necessárias por circunstâncias ou fatos revelados na instrução.', ['Acusação, querelante e assistente; depois acusado.', 'Pedido deve explicar relação com o que surgiu.', 'Não confundir com adiamento sem finalidade.'], 'O momento não legitima pedido protelatório desconectado da instrução.', 'Testemunha revela documento antes desconhecido: defesa pede diligência justificada.', 'Pedido repetido sem utilidade nem nexo pode ser examinado para indeferimento fundamentado.', ['Necessidade deve decorrer do apurado na instrução? Sim.', 'Pedido protelatório é direito irrestrito? Não.'], 'Diligência complementar','Providência necessária por elemento surgido na prova.')
add(403,'Sem diligências pendentes, alegações finais orais seguem acusação e defesa: vinte minutos, prorrogáveis por dez.', ['Cada acusado tem tempo de defesa individual.', 'Assistente: dez minutos após MP; acrescenta igual período à defesa.', 'Complexidade ou vários acusados permitem memoriais sucessivos de cinco dias.', 'Com memoriais, sentença em dez dias.'], 'Não dividir um único tempo de defesa entre todos os acusados nem tornar simultâneos os prazos sucessivos.', 'Dois acusados recebem cada qual seu tempo defensivo.', 'Caso complexo pode ter memoriais com defesa após acusação e prazo de sentença próprio.', ['Defesa de cada acusado tem tempo individual? Sim.', 'Memoriais do §3º são simultâneos? Não.'], 'Alegações finais','Última manifestação sobre prova antes da decisão.')
add(404,'Diligência imprescindível encerra audiência sem alegações finais; concluída a diligência, seguem memoriais sucessivos.', ['Cinco dias sucessivos para partes.', 'Dez dias para sentença após memoriais.', 'Fundamentar necessidade e respeitar sistema acusatório.'], 'Não sentenciar ignorando oportunidade de manifestação sobre prova nova imprescindível.', 'Documento necessário é obtido e partes se manifestam antes da sentença.', 'Sem diligência imprescindível, não aplicar este regime apenas para adiar julgamento.', ['Memoriais vêm depois da diligência? Sim.', 'Prazo das partes é sucessivo? Sim.'], 'Diligência imprescindível','Prova necessária antes das manifestações finais.')
add(405,'Audiência é documentada em termo; gravação, sobretudo audiovisual, busca fidelidade e dispensa transcrição nesse caso.', ['Termo com resumo relevante e assinaturas previstas.', 'Sempre que possível utilizar recursos de registro.', 'Cópia do registro original encaminhada às partes no audiovisual.'], 'Dispensar transcrição não significa dispensar acesso da defesa à gravação.', 'Partes recebem cópia da audiência audiovisual para consultar depoimentos.', 'Arquivo inacessível não satisfaz contraditório apenas porque a lei dispensa degravação.', ['Audiovisual exige sempre transcrição integral? Não.', 'Partes devem receber cópia do registro original? Sim.'], 'Registro audiovisual','Documentação fiel com acesso às partes.')
assert len(rows)==14
Path(sys.argv[1]).write_text(json.dumps({'course_slug':'codigo-processo-penal','units':rows},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(len(rows),'common procedure units reviewed')
